//! Round 39c „Developer documentation on the website, user help gaps, rest of the interface literals“, task docs_site,
//! owner docs_site: developer documentation on the website (English).
//!
//! The pages under `/en/docs/` are generated by `site/tools/docs_pages.py` from nine files in `docs/` and mounted
//! into the English site by `site/hugo.toml`; `scripts/ci-site.sh` runs the generator before Hugo. Hugo and
//! `scripts/site-check.py` check the built pages in the CI (and `scripts/ci-selftest.sh` the generator itself); here
//! is what holds the arrangement together without building: menu entries, the list of sources with their fixed
//! addresses, the output outside `site/content`, the order in `ci-site.sh` and the decision that the output is not
//! checked in (contract §2.6).

use std::path::{Path, PathBuf};

fn repo() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn repo_file(path: &str) -> String {
    std::fs::read_to_string(repo().join(path)).unwrap_or_else(|e| panic!("{path} is readable: {e}"))
}

/// The nine sources with the fixed slug of `/en/docs/<slug>/` and the weight (contract §2.3).
const SOURCES: [(&str, &str, u32); 9] = [
    ("Bedienung.md", "usage", 10),
    ("Architektur.md", "architecture", 20),
    ("RPC.md", "rpc", 30),
    ("MCP.md", "mcp", 40),
    ("Austauschformat.md", "exchange-format", 50),
    ("WYSIWYG.md", "wysiwyg", 60),
    ("Betrieb.md", "operation", 70),
    ("Verteilung.md", "distribution", 80),
    ("Plan.md", "plan", 90),
];

/// The `key = value` lines of every `[[<table>]]` block in `hugo.toml`, one map per block (values with quotes).
fn menu_entries(toml: &str, table: &str) -> Vec<Vec<(String, String)>> {
    let header = format!("[[{table}]]");
    let mut entries = Vec::new();
    let mut current: Option<Vec<(String, String)>> = None;
    for line in toml.lines() {
        let line = line.trim();
        if line.starts_with('[') {
            if let Some(entry) = current.take() {
                entries.push(entry);
            }
            if line == header {
                current = Some(Vec::new());
            }
            continue;
        }
        if let (Some(entry), Some((key, value))) = (current.as_mut(), line.split_once('=')) {
            entry.push((key.trim().to_owned(), value.trim().to_owned()));
        }
    }
    entries.extend(current);
    entries
}

fn value<'a>(entry: &'a [(String, String)], key: &str) -> Option<&'a str> {
    entry.iter().find(|(k, _)| k == key).map(|(_, v)| v.as_str())
}

#[test]
fn both_main_menus_lead_to_the_english_documentation() {
    let toml = repo_file("site/hugo.toml");
    let english = menu_entries(&toml, "languages.en.menus.main");
    let entry = english.iter().find(|e| value(e, "name") == Some("\"Documentation\"")).unwrap_or_else(|| {
        panic!("the English main menu has the entry \"Documentation\" (contract §2.5): {english:?}")
    });
    assert_eq!(
        value(entry, "pageRef"),
        Some("\"/docs\""),
        "the English entry names the section by pageRef, so Hugo marks it as current on every page below /en/docs/"
    );
    assert_eq!(value(entry, "weight"), Some("60"), "weight 60 puts the entry after \"MCP and assistants\" (50)");

    let german = menu_entries(&toml, "languages.de.menus.main");
    let entry = german
        .iter()
        .find(|e| value(e, "name") == Some("\"Dokumentation (englisch)\""))
        .unwrap_or_else(|| panic!("the German main menu has „Dokumentation (englisch)“ (contract §2.5): {german:?}"));
    assert_eq!(
        value(entry, "url"),
        Some("\"/en/docs/\""),
        "there is no German documentation page; the German entry points to the English section by address (a pageRef \
         would look for a German page and find none)"
    );
    assert_eq!(value(entry, "pageRef"), None, "url and pageRef together would be ambiguous");
    assert_eq!(value(entry, "weight"), Some("60"), "same place as in the English menu");
}

#[test]
fn the_generator_lists_exactly_the_nine_sources_with_their_fixed_addresses() {
    let generator = repo_file("site/tools/docs_pages.py");
    let table = generator
        .split_once("DOCS = (")
        .and_then(|(_, rest)| rest.split_once("\n)\n"))
        .map(|(table, _)| table)
        .expect("docs_pages.py has the table DOCS = ( … ) with one entry per source");
    for (source, slug, weight) in SOURCES {
        let entry = format!("(\"{source}\", \"{slug}\", {weight},");
        assert!(
            table.contains(&entry),
            "DOCS names docs/{source} with the address /en/docs/{slug}/ and weight {weight}: others may link to the \
             fixed addresses of contract §2.3 (missing: {entry})"
        );
        assert!(
            repo().join("docs").join(source).is_file(),
            "docs/{source} exists: the generator stops when a listed source is missing, and the CI with it"
        );
    }
    let entries = table.lines().filter(|l| l.trim_start().starts_with("(\"")).count();
    assert_eq!(entries, SOURCES.len(), "no tenth source: contract §2.1 names exactly these nine files");
    assert!(
        generator.contains("URL_BASE = \"/en/docs/\""),
        "the section lives at /en/docs/ (contract §2.3), the index there"
    );
}

#[test]
fn the_output_lies_outside_site_content_and_is_mounted_for_english_only() {
    let generator = repo_file("site/tools/docs_pages.py");
    assert!(
        generator.contains("OUTPUT = os.path.join(\"generated\", \"docs\")"),
        "the generator writes to site/generated/docs (contract §2.2): under site/content the help tests would demand a \
         German twin for every generated page"
    );
    for lang in ["de", "en"] {
        assert!(
            !repo().join("site/content").join(lang).join("docs").exists(),
            "no folder site/content/{lang}/docs: the documentation is generated, never kept by hand in the content"
        );
    }
    let toml = repo_file("site/hugo.toml");
    let module = toml.split_once("\n[module]\n").map(|(_, m)| m).expect("hugo.toml has a [module] table with mounts");
    let mounts: Vec<&str> = module.split("[[module.mounts]]").skip(1).collect();
    let generated = mounts
        .iter()
        .find(|m| m.contains("source = \"generated\""))
        .expect("hugo.toml mounts site/generated (the output of the generator)");
    assert!(
        generated.contains("target = \"content\"") && generated.contains("languages = [\"en\"]"),
        "generated/ is content of the language en only: the pages are English, the German site has none (contract §2.2)"
    );
    for lang in ["de", "en"] {
        assert!(
            mounts.iter().any(|m| m.contains(&format!("source = \"content/{lang}\""))
                && m.contains(&format!("languages = [\"{lang}\"]"))),
            "content/{lang} stays mounted for {lang}: a configured content mount replaces the contentDir defaults, \
             without it the hand-written pages would vanish"
        );
    }
}

#[test]
fn ci_site_runs_the_generator_before_hugo_and_checks_the_pages() {
    let script = repo_file("scripts/ci-site.sh");
    let generator = script
        .find("\"$python\" -I \"$docs_generator\" --site")
        .expect("ci-site.sh runs site/tools/docs_pages.py with python3 -I (contract §2.1)");
    let hugo = script.find("\"$hugo\" --minify --panicOnWarning -s \"$site\"").expect("ci-site.sh builds with Hugo");
    assert!(
        generator < hugo,
        "the generator runs before Hugo, otherwise Hugo would build stale or no documentation pages"
    );
    assert!(
        script.contains("docs_generator=\"$site/tools/docs_pages.py\""),
        "the generator belongs to the site; the invented sites of ci-selftest.sh have none and skip the step"
    );
    let check = script.find("index.html fehlt (Mount generated/").expect("ci-site.sh checks the generated pages");
    assert!(
        check > hugo,
        "after the build ci-site.sh checks that /en/docs/ and every listed page exist (a missing mount builds silently)"
    );
    let pages = repo_file(".github/workflows/pages.yml");
    assert!(
        pages.contains("sh scripts/ci-site.sh") && !pages.contains("docs_pages.py"),
        "pages.yml needs no step of its own: ci-site.sh runs the generator (contract §2.1)"
    );
}

#[test]
fn the_generated_pages_are_not_checked_in_and_the_decision_is_documented() {
    let ignore = repo_file(".gitignore");
    assert!(
        ignore.lines().any(|l| l.trim() == "site/generated/"),
        ".gitignore names site/generated/: the pages are rebuilt on every site build from docs/, a committed copy \
         would fall behind with every documentation change (decision of contract §2.2)"
    );
    let readme = repo_file("site/README.md");
    let distribution = repo_file("docs/Verteilung.md");
    for (name, text) in [("site/README.md", &readme), ("docs/Verteilung.md", &distribution)] {
        assert!(
            text.contains("site/generated/") && text.contains("docs_pages.py") && text.contains("not checked in"),
            "{name} documents the generator, its output folder and that the output is not checked in (contract §2.7)"
        );
    }
    let tools = repo_file("site/tools/README.md");
    assert!(tools.contains("docs_pages.py"), "site/tools/README.md describes the generator next to the other tools");
}

#[test]
fn the_theme_has_the_documentation_layout_and_its_strings_in_both_languages() {
    let page = repo_file("site/themes/baruch/layouts/docs/page.html");
    assert!(
        page.contains("T \"docs_seiten\"") && page.contains(".Params.quelle"),
        "the documentation pages have their own navigation (label docs_seiten) and name their source file"
    );
    let section = repo_file("site/themes/baruch/layouts/docs/section.html");
    assert!(section.contains(".Pages.ByWeight"), "the index /en/docs/ lists the pages in the order of their weights");
    for lang in ["en", "de"] {
        let strings = repo_file(&format!("site/themes/baruch/i18n/{lang}.toml"));
        let own = strings
            .split_once("# Documentation section and menu (Round 39c, owner docs_site)")
            .map(|(_, rest)| rest)
            .unwrap_or_else(|| panic!("i18n/{lang}.toml keeps the S1 comment of docs_site"));
        for key in ["docs_seiten", "docs_quelle", "docs_quelle_hinweis"] {
            assert!(
                own.contains(&format!("[{key}]")),
                "i18n/{lang}.toml has [{key}] below the comment of docs_site (contract §1c, same keys in both files)"
            );
        }
        let before = strings.split_once("# Documentation section and menu").map(|(b, _)| b).unwrap_or_default();
        assert!(!before.contains("[docs_"), "docs_* keys stand only below the comment of docs_site in {lang}.toml");
    }
}
